def construct_matrix(n):
    A = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            # A_{i, j} = (floor(i/3) + floor(j/3) + (i+j) mod 3) mod 3
            val = (i // 3 + j // 3 + (i + j) % 3) % 3
            A[i][j] = val
    return A

n = 39
A = construct_matrix(n)

def check_row_balance(matrix, n):
    counts = {0: 0, 1: 0, 2: 0}
    for j in range(n):
        for i in range(n):
            counts[matrix[i][j]] += 1 # Checking column balance for clarity

    # Let's check row balance
    row_counts = []
    for i in range(n):
        counts = {0: 0, 1: 0, 2: 0}
        for j in range(n):
            counts[matrix[i][j]] += 1
        row_counts.append(counts)

    return row_counts

row_counts = check_row_balance(A, n)

print(f"Checked Row Balance for n={n}. Required count: {n//3}")
all_balanced = True
for i, counts in enumerate(row_counts):
    if counts[0] != n//3 or counts[1] != n//3 or counts[2] != n//3:
        print(f"Row {i} is UNBALANCED: {counts}")
        all_balanced = False

if all_balanced:
    print("All rows are balanced.")
else:
    print("Not all rows are balanced.")
